alter table public.community_comments add column if not exists parent_comment_id uuid references public.community_comments(id) on delete cascade; create index if not exists community_comments_parent_comment_id_idx on public.community_comments(parent_comment_id); alter table public.profiles add column if not exists bio text; alter table public.profiles add column if not exists location text; alter table public.profiles add column if not exists website text; alter table public.profiles add column if not exists instagram text; alter table public.profiles add constraint profiles_bio_length_check check (bio is null or char_length(bio) <= 280); alter table public.profiles add constraint profiles_location_length_check check (location is null or char_length(location) <= 80); alter table public.profiles add constraint profiles_website_length_check check (website is null or char_length(website) <= 200); alter table public.profiles add constraint profiles_instagram_length_check check (instagram is null or char_length(instagram) <= 30); create or replace function public.protect_profile_admin_fields() returns trigger language plpgsql security definer set search_path=public as $$ begin if auth.uid() is not null and coalesce(auth.jwt()->'app_metadata'->>'role','') <> 'admin' then new.is_admin := old.is_admin; end if; return new; end; $$; drop trigger if exists protect_profile_admin_fields on public.profiles; create trigger protect_profile_admin_fields before update on public.profiles for each row execute function public.protect_profile_admin_fields();